    /// dependents. Prefer a guarded composition (read + validated writes) for any
    /// real deployment; use this only in trusted/admin/seeding contexts.
    pub fn all_crud_routes(&self) -> Router {
        use presentation::http::{
            create_contact_message_read_routes,
            create_menu_read_routes,
            create_menu_block_read_routes,
            create_page_read_routes,
            create_page_block_read_routes,
            create_redirect_read_routes,
            create_visitor_read_routes,
            create_visitor_track_read_routes,
            create_website_read_routes,
            create_website_audit_log_read_routes,
            create_website_member_read_routes,
        };

        Router::new()
            .merge(create_contact_message_read_routes(self.contact_message_service.clone()))
            .merge(create_menu_read_routes(self.menu_service.clone()))
            .merge(create_menu_block_read_routes(self.menu_block_service.clone()))
            .merge(create_page_read_routes(self.page_service.clone()))
            .merge(create_page_block_read_routes(self.page_block_service.clone()))
            .merge(create_redirect_read_routes(self.redirect_service.clone()))
            .merge(create_visitor_read_routes(self.visitor_service.clone()))
            .merge(create_visitor_track_read_routes(self.visitor_track_service.clone()))
            .merge(create_website_read_routes(self.website_service.clone()))
            .merge(create_website_audit_log_read_routes(self.website_audit_log_service.clone()))
            .merge(create_website_member_read_routes(self.website_member_service.clone()))
    }

    /// Deprecated alias for [`Self::all_crud_routes`]. `routes()` reads like
