        Router::new()
            .merge(create_contact_message_read_routes(self.contact_message_service.clone()))
            .merge(create_menu_read_routes(self.menu_service.clone()))
            .merge(create_menu_block_read_routes(self.menu_block_service.clone()))
            .merge(create_page_read_routes(self.page_service.clone()))
